def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def components(a):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                color = a[r][c]
                if color == 7 or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                while stack:
                    x, y = stack.pop()
                    comp.append((x, y))
                    for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                        if (0 <= nx < h and 0 <= ny < w and
                                (nx, ny) not in seen and a[nx][ny] == color):
                            seen.add((nx, ny))
                            stack.append((nx, ny))
                result.append((color, comp))
        return result

    # Restore small defects inside dense, nearly rectangular colored regions.
    for color, comp in components(out):
        if len(comp) < 6:
            continue
        r0 = min(r for r, c in comp)
        r1 = max(r for r, c in comp)
        c0 = min(c for r, c in comp)
        c1 = max(c for r, c in comp)
        area = (r1 - r0 + 1) * (c1 - c0 + 1)
        if len(comp) / area >= 0.8:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color

    # Recolor isolated stray cells from their four-connected surroundings.
    for _ in range(3):
        changes = {}
        for color, comp in components(out):
            if len(comp) > 2:
                continue
            for r, c in comp:
                neighbors = [
                    out[nr][nc]
                    for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1))
                    if 0 <= nr < h and 0 <= nc < w
                ]
                counts = {}
                for value in neighbors:
                    counts[value] = counts.get(value, 0) + 1
                if counts:
                    best = max(counts.values())
                    choices = [v for v, n in counts.items() if n == best]
                    changes[(r, c)] = 7 if 7 in choices else choices[0]
        if not changes:
            break
        for (r, c), value in changes.items():
            out[r][c] = value

    return out
